from hypothesis import given, settings, strategies as st

from solution import Service


class Clock:
    def __init__(self, t=1000.0):
        self.t = t

    def now(self):
        return self.t


class Gateway:
    def __init__(self):
        self.charged = {}

    def charge(self, reference, amount_cents):
        self.charged.setdefault(reference, amount_cents)
        return True


PW = "password1"
SETTINGS = settings(max_examples=40, deadline=None)

surrogate_pw = st.lists(st.integers(0xD800, 0xDFFF).map(chr), min_size=8, max_size=12).map("".join)


def make():
    svc = Service(Clock(), Gateway())
    assert svc.register("alice", PW)[0] == 201
    s, b = svc.login("alice", PW)
    assert s == 200
    return svc, b["token"]


def test_login_with_unencodable_wrong_password_is_401():
    """Login with anything other than the correct credentials returns 401, including a password of lone surrogates."""
    svc, _ = make()
    pw = "\ud800" * 8
    out = svc.login("alice", pw)
    assert out == (401, None), f"input={pw!r} output={out!r}"


@given(surrogate_pw)
@SETTINGS
def test_property_login_with_surrogate_password_is_401(pw):
    """Login with a password that is not the registered one returns 401, whatever characters it contains."""
    svc, _ = make()
    out = svc.login("alice", pw)
    assert out == (401, None), f"input={pw!r} output={out!r}"


def test_register_with_surrogate_password_status_is_specified():
    """Register returns only 201, 400 or 409, even for an 8-character password of lone surrogates."""
    svc = Service(Clock(), Gateway())
    pw = "\ud800" * 8
    out = svc.register("carol", pw)
    assert out[0] in (201, 400), f"input={pw!r} output={out!r}"


@given(surrogate_pw)
@SETTINGS
def test_property_register_status_in_specified_set(pw):
    """For a fresh valid username, register returns 201 or 400 only."""
    svc = Service(Clock(), Gateway())
    out = svc.register("carol", pw)
    assert out[0] in (201, 400), f"input={pw!r} output={out!r}"


def test_pay_empty_key_with_valid_token_is_not_401():
    """401 is reserved for bad tokens, so pay with a valid token never returns 401."""
    svc, tok = make()
    out = svc.pay(tok, 100, "")
    assert out[0] in (201, 400), f"input=(100, '') output={out!r}"


@given(st.integers(1, 1000000))
@SETTINGS
def test_property_pay_empty_key_never_401(amount):
    """With a valid token and a valid amount, pay does not return 401 whatever the key."""
    svc, tok = make()
    out = svc.pay(tok, amount, "")
    assert out[0] in (201, 400), f"input=({amount!r}, '') output={out!r}"


def test_pay_bad_token_is_401_even_with_invalid_amount():
    """Pay with a missing, unknown or revoked token returns 401 regardless of the amount."""
    svc, tok = make()
    svc.logout(tok)
    for t in [None, "unknown", tok]:
        for amt in [100, 0, -5, 1000001]:
            out = svc.pay(t, amt, "k")
            assert out == (401, None), f"token={t!r} amount={amt!r} output={out!r}"


def test_pay_expired_token_is_401():
    """Pay with an expired token returns 401."""
    clock = Clock()
    svc = Service(clock, Gateway(), token_ttl=10)
    svc.register("alice", PW)
    tok = svc.login("alice", PW)[1]["token"]
    clock.t += 10
    for amt in [100, 0]:
        out = svc.pay(tok, amt, "k")
        assert out == (401, None), f"amount={amt!r} output={out!r}"


